R=[
(9794716,"वीगन शकरकंद बर्गर [बिना तेल के]","ये वीगन शकरकंद बर्गर स्वाद से भरपूर हैं, इनकी बनावट शानदार है और किनारे बिल्कुल कुरकुरे हैं। बेहद स्वादिष्ट, हल्के से मसाले के साथ, और वीगन तथा मांसाहारी, दोनों को पसंद आने वाले।","8 बर्गर","1 बर्गर",
["1.5 कप कटे हुए शकरकंद के टुकड़े, लगभग 1 छोटा शकरकंद","1 पीला प्याज, टुकड़ों में कटा हुआ","1 लाल शिमला मिर्च, टुकड़ों में कटी हुई","4-6 क्रेमिनी या बेबी बेला मशरूम, टुकड़ों में कटे हुए","15 औंस का 1 डिब्बा सफेद राजमा, छाना और धुला हुआ","1 छोटा चम्मच समुद्री नमक","1 छोटा चम्मच लहसुन पाउडर","½ छोटा चम्मच जीरा","¼ छोटा चम्मच लाल मिर्च (कैयेन)","¾ कप रोल्ड ओट्स, चाहें तो ग्लूटेन-मुक्त","वैकल्पिक टॉपिंग::कटा हुआ टमाटर, अचार, लाल प्याज, एवोकाडो, अचारी मिर्च, डिल, पार्सली या हरा धनिया जैसी ताज़ी जड़ी-बूटियां"],
["एक छोटे पतीले में कटा हुआ शकरकंद डालें, पानी से ढकें और उबाल लें। कांटे से आसानी से छिदने तक, लगभग 10 मिनट पकाएं। फिर छान लें और एक तरफ रख दें।",
"इसी बीच, कटा हुआ प्याज, शिमला मिर्च और मशरूम एक बड़े पैन में डालें। नमक और काली मिर्च छिड़कें और नरम होने तक, लगभग 5 मिनट बिना तेल के भूनें। (मशरूम पानी छोड़ेंगे, इसलिए भूनने के लिए आपको तेल या पानी की ज़रूरत नहीं होनी चाहिए।)",
"पका हुआ शकरकंद, राजमा और मसाले अपने फूड प्रोसेसर में डालें। टूटने तक चलाएं, लेकिन चिकना न करें। आप थोड़ी बनावट बनाए रखना चाहते हैं। फिर भुनी हुई सब्जियां और ओट्स डालें और मिलाने के लिए कुछ बार पल्स करें। प्यूरी न बनाएं।",
"एक बेकिंग ट्रे में बटर पेपर बिछाएं और गीले हाथों से अपने घोल से टेनिस की गेंद के आकार के गोले बनाएं। फिर उन्हें चपटा करके टिक्की का आकार दें और अपनी ट्रे पर रखें। आपको 8 टिक्कियां मिलनी चाहिए। कम से कम 30 मिनट, या अगर पहले से तैयारी कर रहे हैं तो रात भर फ्रिज में रखें।",
"बेक करने के लिए तैयार होने पर, अपना ओवन 450 डिग्री F पर गरम करें और 25 मिनट बेक करें। फिर बर्गर को सावधानी से पलटें और 15 मिनट और बेक करें, जब तक किनारे सुनहरे भूरे न हो जाएं।"],
["ज़्यादा प्रोसेस न करें। यहां आप अच्छी बनावट वाला बर्गर चाहते हैं, इसलिए फूड प्रोसेसर में ज़्यादा न चलाएं। अगर आपके पास छोटा प्रोसेसर है, तो कई बार में काम करें। सब कुछ छोटे उपकरण में ठूंसने की कोशिश न करें, वरना नीचे का हिस्सा प्यूरी बन जाएगा और ऊपर का हिस्सा दरदरा रहेगा। इससे सबसे अच्छी बनावट नहीं मिलेगी। अपनी टिक्कियां बनाने के लिए गीले हाथों का इस्तेमाल करें! घोल थोड़ा चिपचिपा होगा, इसलिए गीले हाथों से टिक्कियां हाथों में नहीं चिपकेंगी। घोल को चखें और ज़रूरत हो तो मसाले ठीक करें। घोल प्रोसेस हो जाने के बाद, एक नमूना चखें और ज़रूरत हो तो और नमक, काली मिर्च, लहसुन पाउडर, जीरा या लाल मिर्च डालें। हमेशा अपने स्वाद के अनुसार मसाले डालें। इसे धुएं वाला स्वाद दें। अगर आप अपने बर्गर में धुएं जैसा स्वाद जोड़ना चाहते हैं, तो घोल में ½ छोटा चम्मच स्मोक्ड पैपरिका डालें। बचे हुए बर्गर फ्रिज में 3-4 दिन तक रखे जा सकते हैं या एयरटाइट डिब्बे में 3 महीने तक फ्रीज़ किए जा सकते हैं।"],
[]),
(9794865,"एयर फ्रायर शकरकंद के टुकड़े","बाहर से कुरकुरे और अंदर से नरम और मुलायम। इस एयर फ्रायर शकरकंद व्यंजन को दो स्वादिष्ट स्वादों में बनाएं!","4 सर्विंग","1 सर्विंग",
["2 पाउंड शकरकंद, छिले हुए + आधा इंच के टुकड़ों में कटे हुए (लगभग 6 कप कटे हुए)","तीखा संस्करण::2 बड़े चम्मच कम सोडियम वाला सब्जियों का शोरबा","तीखा संस्करण::½ छोटा चम्मच समुद्री नमक या स्वादानुसार (अगर सामान्य शोरबा इस्तेमाल कर रहे हैं तो छोड़ दें)","तीखा संस्करण::½ छोटा चम्मच लहसुन पाउडर","तीखा संस्करण::½ छोटा चम्मच लाल मिर्च पाउडर","तीखा संस्करण::½ छोटा चम्मच लाल मिर्च (कैयेन)","तीखा संस्करण::½ छोटा चम्मच काली मिर्च","मीठा संस्करण::2 बड़े चम्मच मेपल सिरप","मीठा संस्करण::1 छोटा चम्मच दालचीनी","मीठा संस्करण::⅛ छोटा चम्मच समुद्री नमक, वैकल्पिक"],
["अपने शकरकंद को छीलकर आधा इंच के टुकड़ों में काट लें। उन्हें एक मध्यम आकार के बाउल में रखें। अपनी पसंद के स्वाद (तीखा या मीठा, दोनों नहीं) के सारे मसाले ऊपर डालें और बराबर लगाने के लिए अच्छी तरह मिलाएं।",
"मसाले लगे शकरकंद के टुकड़े अपने फ्रायर की टोकरी में एक परत में रखें। (ज़रूरत हो तो कई बार में पकाएं।) फिर 400 डिग्री F पर 18-22 मिनट एयर फ्राई करें, हर 5 मिनट में हिलाएं या मिलाएं। पकने का समय मात्रा और फ्रायर के मॉडल के अनुसार अलग-अलग होगा।"],
["अगर आपकी फ्रायर की टोकरी छोटी है तो कई बार में काम करें और पकने के अंत की ओर अपने शकरकंद को बार-बार देखते रहें। अपनी टोकरी में ज़्यादा न भरें। मात्रा और फ्रायर का मॉडल पकने का समय तय करेंगे। कम मात्रा जल्दी पकती है, और आपकी दूसरी खेप पहली से जल्दी पकेगी, इसलिए पकाते समय अपने शकरकंद को देखते रहें। ये तुरंत खाने पर सबसे अच्छे लगते हैं, लेकिन बचे हुए फ्रिज में 3-4 दिन तक रखे जा सकते हैं। यह रेसिपी मेरे एयर फ्राइड बटरनट स्क्वैश से प्रेरित है। ***नीचे दी गई पोषण संबंधी जानकारी तीखे संस्करण के एक-चौथाई हिस्से के लिए है। मीठे संस्करण में प्रति सर्विंग 223 कैलोरी और 15 ग्राम चीनी है।"],
[]),
(9798062,"मूंगफली की सॉस वाला टोफू बुद्धा बाउल","कुरकुरा टोफू, स्वादिष्ट मूंगफली की सॉस, अनाज और ताज़ी सब्जियां इस टोफू बुद्धा बाउल को यादगार बना देती हैं!","4 सर्विंग","1 सर्विंग",
["कुरकुरे टोफू के लिए::350 ग्राम (12 औंस) का 1 ब्लॉक एक्स्ट्रा सख्त टोफू, आधा इंच के टुकड़ों में कटा हुआ (हो सके तो GMO-मुक्त इस्तेमाल करें)","कुरकुरे टोफू के लिए::2 बड़े चम्मच कम सोडियम वाली सोया सॉस या ग्लूटेन-मुक्त के लिए तमारी","कुरकुरे टोफू के लिए::2 बड़े चम्मच एरोरूट पाउडर या कॉर्नस्टार्च","कुरकुरे टोफू के लिए::1 छोटा चम्मच प्याज पाउडर","कुरकुरे टोफू के लिए::1 छोटा चम्मच लहसुन पाउडर","मूंगफली की सॉस के लिए::⅓ कप चिकना पीनट बटर, कुदरती वाला जिसमें तेल या चीनी न मिलाई गई हो","मूंगफली की सॉस के लिए::2 बड़े चम्मच चावल का सिरका","मूंगफली की सॉस के लिए::2 बड़े चम्मच नींबू (लाइम) का रस, लगभग 1 नींबू","मूंगफली की सॉस के लिए::2 बड़े चम्मच सोया सॉस या ग्लूटेन-मुक्त के लिए तमारी","मूंगफली की सॉस के लिए::1-2 लहसुन की कलियां, बारीक कटी हुई","मूंगफली की सॉस के लिए::½ बड़ा चम्मच ताज़ा कद्दूकस की हुई अदरक","मूंगफली की सॉस के लिए::1-2 बड़े चम्मच छना हुआ पानी, पतला करने के लिए","परोसने के लिए (वैकल्पिक)::ब्राउन राइस, नूडल्स या क्विनोआ","परोसने के लिए (वैकल्पिक)::कद्दूकस की हुई बैंगनी पत्तागोभी, गाजर, लाल शिमला मिर्च की पट्टियां, आधे कटे अंगूर जैसे टमाटर, कटा हुआ खीरा, एवोकाडो, हरी प्याज जैसी सब्जियां"],
["ओवन को 425℉/218℃ पर पहले से गरम करें और बेकिंग शीट पर बटर पेपर बिछा दें।",
"टोफू के टुकड़े एक मध्यम बाउल में रखें और सोया सॉस डालें। टुकड़ों पर लगाने के लिए धीरे से मिलाएं। फिर एरोरूट और मसाले डालें और बराबर लगने तक चलाएं।",
"मसाले लगे टुकड़ों को अपनी बटर पेपर बिछी ट्रे पर एक परत में सजाएं। फिर 15 मिनट बेक करें, टुकड़ों को पलटें, और मनचाही कुरकुराहट आने तक 8-10 मिनट और बेक करें।",
"जब टोफू बेक हो रहा हो, तब मूंगफली की सॉस की सारी सामग्री एक छोटे बाउल में डालें और मिलने तक मिलाएं, और अपने पसंदीदा गाढ़ेपन तक पतला करने के लिए 1-2 बड़े चम्मच पानी डालें।",
"अपनी पसंद की ताज़ी सब्जियों और अपनी पसंद के अनाज के साथ परोसें, और हर बाउल पर मूंगफली की सॉस डालें, या उसे डुबोने के लिए अलग से परोसें।"],
["अगर इसके लिए आप एक्स्ट्रा सख्त टोफू इस्तेमाल कर रहे हैं, तो उसे दबाने की ज़रूरत नहीं है। मैंने दोनों तरह से आज़माया है, और फर्क बहुत मामूली था। फिर भी, अगर आप चाहें तो पहले उसे दबा सकते हैं।","बराबर पकने के लिए टोफू के टुकड़े एक ही आकार के काटने की पूरी कोशिश करें।","टुकड़ों को एक परत में, बीच में काफ़ी जगह छोड़कर सजाना न भूलें ताकि वे अच्छी तरह कुरकुरे हो जाएं।","बचा हुआ फ्रिज में 3-4 दिन तक रखा जा सकता है।"],
[]),
(9801698,"यक़ीन नहीं होता कि यह वीगन पुटीन है!","चीज़ कर्ड्स वाली वीगन पुटीन, जो चर्र-चर्र की आवाज़ करते हैं!!! यह सबसे बेहतरीन वीगन पुटीन है और इसका स्वाद सचमुच असली जैसा है। इससे बेहतर कुछ नहीं हो सकता!","3 सर्विंग","1 सर्विंग",
["फ्राइज़ के लिए::1.5 पाउंड रसेट आलू, लगभग 3 बड़े आलू","फ्राइज़ के लिए::1 छोटा चम्मच एवोकाडो तेल, बिना तेल के लिए इसकी जगह 1 बड़ा चम्मच शोरबा डालें","फ्राइज़ के लिए::½ छोटा चम्मच समुद्री नमक","फ्राइज़ के लिए::½ छोटा चम्मच सूखा रोज़मेरी","फ्राइज़ के लिए::1 बड़ा चम्मच कॉर्नस्टार्च","चीज़ कर्ड्स के लिए::½ रेसिपी वीगन मोज़ेरेला चीज़","ग्रेवी के लिए::100 ग्राम क्रेमिनी मशरूम, पतले कटे हुए, लगभग 4-5 छोटे","ग्रेवी के लिए::1 छोटा चम्मच तमारी या सोया सॉस, अगर ग्लूटेन से परहेज़ नहीं है","ग्रेवी के लिए::1 कप कम सोडियम वाला सब्जियों का शोरबा","ग्रेवी के लिए::1 बड़ा चम्मच ब्राउन राइस का आटा या मैदा, अगर ग्लूटेन से परहेज़ नहीं है","वैकल्पिक सजावट::हरी प्याज"],
["सबसे पहले, वीगन मोज़ेरेला चीज़ बनाएं, उसे किसी डिब्बे या बाउल में डालें और ठंडा होने के लिए फ्रिज में रख दें।",
"अपने ओवन को 425 डिग्री F पर कन्वेक्शन बेक पर पहले से गरम करें और एक बड़ी बेकिंग ट्रे में बटर पेपर बिछा दें।",
"आलू को छीलें या रगड़कर साफ़ करें और फ्रेंच फ्राई कटर या तेज़ चाकू से फ्राइज़ के आकार में काट लें।",
"फ्रेंच फ्राइज़ को तेल, नमक, रोज़मेरी और कॉर्नस्टार्च के साथ बराबर लगने तक मिलाएं। फिर उन्हें अपनी तैयार ट्रे पर एक परत में फैला दें। 20-25 मिनट बेक करें, फिर अपने फ्राइज़ पलटें और मनचाही कुरकुराहट आने तक 15-20 मिनट और बेक करें।",
"जब फ्राइज़ बेक हो रहे हों, तब ग्रेवी बनाएं। कटे हुए मशरूम और तमारी एक छोटे पतीले में डालें और मध्यम आंच पर मशरूम के सिकुड़ने तक, लगभग 5 मिनट पकाएं। शोरबा डालें और उबाल आने दें, 1-2 मिनट पकाते रहें।",
"इसी बीच, एक अलग छोटे बाउल में 1 बड़ा चम्मच आटे को 1 बड़े चम्मच पानी के साथ मिलाकर अपना घोल बनाएं। (इससे आपकी ग्रेवी गाढ़ी होगी।) फिर घोल को पतीले में डालें और मिलाने के लिए अच्छी तरह फेंटें। 1 मिनट और पकाएं और आंच से उतार लें। ठंडा होना शुरू होने पर ग्रेवी और गाढ़ी हो जाएगी।",
"अपनी पुटीन को जमाएं, पहले फ्राइज़ की परत लगाएं, और फिर मेलन बॉलर (या छोटे चम्मच) से वीगन चीज़ निकालकर ऊपर \"चीज़ कर्ड्स\" रखें। (कर्ड्स निकालते समय चर्र की आवाज़ सुनें! :)) आखिर में ऊपर से ग्रेवी डालें और चाहें तो हरी प्याज छिड़कें। आनंद लें!!!"],
["सबसे कुरकुरे बेक्ड फ्रेंच फ्राइज़ के लिए और उन्हें चिपकने से बचाने के लिए अपने फ्राइज़ को एक परत में, बीच में काफ़ी जगह छोड़कर सजाना न भूलें। बिना कन्वेक्शन वाले ओवन के लिए, फ्राइज़ को थोड़े ज़्यादा समय तक पकाना पड़ सकता है। मनचाही कुरकुराहट आने तक बेक करते रहें। मशरूम के टुकड़ों के बिना चिकनी ग्रेवी के लिए, पक जाने के बाद आप उसे ब्लेंड कर सकते हैं। अगर आपको मशरूम पसंद नहीं हैं, तो आप पतले कटे प्याज के साथ यही तरीका अपना सकते हैं, या इसकी जगह यह प्याज की ग्रेवी आज़माएं। घोल बनाना न छोड़ें! आपको सीधे गरम ग्रेवी में आटा डालने का मन हो सकता है, लेकिन ऐसा करने से गांठें पड़ जाएंगी। अगर पहले से तैयारी कर रहे हैं, तो आप चीज़ पूरी तरह तैयार करके ज़रूरत तक कुछ दिन फ्रिज में रख सकते हैं।"],
[]),
(9807540,"एयर फ्रायर टमाटर","रसीले, स्वादिष्ट और बेहद लज़ीज़ एयर फ्रायर टमाटर!","3 सर्विंग","1 सर्विंग",
["1 पिंट अंगूर जैसे छोटे टमाटर","1 बड़ा चम्मच बाल्सामिक सिरका","1 छोटा चम्मच सूखा ओरेगैनो","1 छोटा चम्मच लहसुन पाउडर","¼ छोटा चम्मच समुद्री नमक या स्वादानुसार","¼ छोटा चम्मच लाल मिर्च के फ्लेक्स, वैकल्पिक, लेकिन सुझाया गया"],
["सारी सामग्री एक ओवन में रखने लायक बर्तन में डालें जो आपकी एयर फ्रायर की टोकरी में आ सके। टमाटरों पर बराबर लगाने के लिए अच्छी तरह मिलाएं, और बर्तन को अपनी टोकरी के अंदर रख दें।",
"375℉/190℃ पर 8-10 मिनट एयर फ्राई करें, या जब तक टमाटर के छिलके सिकुड़े हुए न दिखें, बीच में एक बार मिलाएं, फिर बर्तन को फ्रायर से निकाल लें।",
"इसे टोस्ट पर, साइड डिश के रूप में या बर्गर की टॉपिंग के रूप में खाएं।"],
["अलग-अलग किस्मों के टमाटर आज़माएं। बीफस्टेक जैसे बड़े टमाटरों के लिए आप स्लाइस भी इस्तेमाल कर सकते हैं। अलग-अलग मॉडल अलग-अलग रफ़्तार से पकाएंगे, इसलिए अपने टमाटरों पर ध्यान से नज़र रखें और लगभग 5 मिनट के बाद उन्हें देखना शुरू करें। बचे हुए फ्रिज में 3-4 दिन तक रखे जा सकते हैं।"],
[]),
(9807591,"तीखा वीगन सलामी","तीखा वीगन सलामी जो मांस जैसा, धुएं की खुशबू वाला, स्वाद से भरपूर और सचमुच लाजवाब है। इसे बनाना आसान है, और इसकी बनावट इतनी बढ़िया चबाने लायक है कि आपको यकीन करना मुश्किल होगा कि यह वीगन है!","6 सर्विंग","1 सर्विंग",
["सूखी सामग्री::1 कप वाइटल व्हीट ग्लूटेन","सूखी सामग्री::2 छोटे चम्मच स्मोक्ड पैपरिका","सूखी सामग्री::2 छोटे चम्मच लहसुन पाउडर","सूखी सामग्री::1 छोटा चम्मच सौंफ","सूखी सामग्री::1 छोटा चम्मच समुद्री नमक","सूखी सामग्री::1 छोटा चम्मच प्याज पाउडर","सूखी सामग्री::1 छोटा चम्मच सूखा ओरेगैनो","सूखी सामग्री::1 छोटा चम्मच सूखी पार्सली","सूखी सामग्री::1 छोटा चम्मच काली मिर्च","सूखी सामग्री::½ छोटा चम्मच मिर्च के फ्लेक्स","गीली सामग्री::½ कप कम सोडियम वाला सब्जियों का शोरबा","गीली सामग्री::2 बड़े चम्मच टमाटर का पेस्ट","गीली सामग्री::1 बड़ा चम्मच एवोकाडो तेल या अपनी पसंद का बिना खास स्वाद वाला तेल","गीली सामग्री::1 बड़ा चम्मच सोया सॉस","गीली सामग्री::2 छोटे चम्मच लिक्विड स्मोक"],
["ओवन के निर्देश::ओवन को 375 डिग्री F पर पहले से गरम करें।",
"ओवन के निर्देश::सारी सूखी सामग्री एक बाउल में मिलाएं और अच्छी तरह मिक्स करें। फिर गीली सामग्री को एक अलग बाउल में मिलाएं और मिलाने के लिए फेंटें।",
"ओवन के निर्देश::गीली सामग्री को सूखी सामग्री में डालें और मिलाना शुरू करें, जब तक ज़्यादातर मिल न जाए और आटे जैसा कुछ न बन जाए। फिर इसे किसी साफ़ सतह या कटिंग बोर्ड पर रखें और हाथों से 1-2 मिनट तक गूंधें और दबाएं। यह मुलायम महसूस होना चाहिए और अच्छी तरह मिला हुआ दिखना चाहिए।",
"ओवन के निर्देश::अब अपने आटे को बराबर आकार के दो टुकड़ों में काटें और उन्हें सलामी के आकार में बेलें जो लगभग 6 इंच लंबे हों। इनका बिल्कुल सही होना ज़रूरी नहीं है, पकने पर ये चिकने हो जाएंगे। फिर हर सलामी को पहले बटर पेपर में और फिर एल्युमीनियम फॉइल में लपेटें, यह पक्का करते हुए कि फॉइल इतनी लंबी हो कि एक-दूसरे पर चढ़ जाए और फिर सिरों को मरोड़ दें। (देखने के लिए ऊपर दी गई प्रक्रिया की तस्वीरें देखें।)",
"ओवन के निर्देश::लपेटी हुई सलामी को बेकिंग शीट पर रखें और 45-55 मिनट बेक करें, बीच में उन्हें पलट दें।",
"ओवन के निर्देश::ओवन से निकालें और फॉइल को धीरे से हटाकर देखें कि सलामी चिकनी दिखती हैं या नहीं, और उसकी सख्ती जांचने के लिए उंगली से दबाएं। वे सख्त महसूस होनी चाहिए, लेकिन दबाव पर थोड़ी दबनी भी चाहिए। ठंडी होने पर वे और सख्त हो जाएंगी।",
"ओवन के निर्देश::पूरी तरह ठंडा होने दें, फिर काटें और पिज़्ज़ा के साथ, सैंडविच में, चारक्यूटरी बोर्ड पर, या नाश्ते के रूप में खाएं।",
"भाप में पकाने के निर्देश::अपनी सलामी तैयार करने के लिए ऊपर दिए गए चरण 2-4 का पालन करें। फिर एक बड़े पतीले में 1-2\" पानी डालें जिसमें आपकी स्टीमर की टोकरी आ जाए, पानी को आपकी टोकरी को छुए बिना। उबाल आने दें और फिर आंच कम करके हल्का उबाल बनाए रखें और सलामी को अपनी टोकरी के अंदर रखें।",
"भाप में पकाने के निर्देश::ढककर 45-60 मिनट भाप में पकाएं, अपने पानी पर नज़र रखें ताकि वह पूरी तरह भाप बनकर उड़ न जाए। लगभग 45 मिनट बाद उन्हें देखना शुरू करें। फॉइल को धीरे से हटाएं, सलामी चिकनी दिखनी चाहिए। उसकी सख्ती जांचने के लिए आप उसे उंगली या चिमटे से दबा सकते हैं। वे सख्त महसूस होनी चाहिए लेकिन दबाव पर थोड़ी दबनी भी चाहिए। ठंडी होने पर वे और सख्त हो जाएंगी।",
"भाप में पकाने के निर्देश::पूरी तरह ठंडा होने दें, फिर काटें और पिज़्ज़ा के साथ, सैंडविच में, चारक्यूटरी बोर्ड पर, या नाश्ते के रूप में खाएं।"],
["एकसमान स्वाद और सबसे अच्छी बनावट के लिए अपने आटे को बहुत अच्छी तरह गूंधना और मिलाना न भूलें। बिल्कुल सही आकार की सलामी बनाने में ज़्यादा समय न लगाएं। बेक करने से पहले वह उबड़-खाबड़ दिखेगी, लेकिन पकने के दौरान अच्छी और चिकनी हो जाती है। अगर आपको फॉइल का खाने को छूना पसंद नहीं है, तो अपनी सलामी और एल्युमीनियम फॉइल की परत के बीच बटर पेपर इस्तेमाल करें। हल्के वीगन सलामी के लिए, बस मिर्च के फ्लेक्स छोड़ दें, लेकिन सबसे अच्छे स्वाद के लिए काली मिर्च बनाए रखें। इसे सीलबंद डिब्बे या ज़िप-टॉप बैग में फ्रिज में 1 हफ्ते तक रखें। या आप इसे 3 महीने तक फ्रीज़ कर सकते हैं।"],
[]),
(9808977,"सेहतमंद एयर फ्रायर पॉपकॉर्न","एयर फ्रायर पॉपकॉर्न एक सेहतमंद और स्वादिष्ट नाश्ता है जिसमें सिर्फ एक सामग्री की ज़रूरत है। कुरकुरे, स्वादिष्ट, बिना अपराधबोध और पूरी तरह संतोषजनक नाश्ते के लिए आपको सिर्फ पॉपकॉर्न के दाने चाहिए।","2 सर्विंग","1 सर्विंग",
["¼ कप पॉपकॉर्न के दाने","वैकल्पिक टॉपिंग::पिघला हुआ मक्खन या तेल","वैकल्पिक टॉपिंग::सफेद सिरका","वैकल्पिक टॉपिंग::नमक + काली मिर्च","वैकल्पिक टॉपिंग::या आपके पसंदीदा मसालों के मिश्रण"],
["अपने फ्रायर को 5 मिनट के लिए 400 डिग्री F पर पहले से गरम करें।",
"फिर एल्युमीनियम फॉइल की एक शीट, जिसके किनारे थोड़े ऊपर की ओर मुड़े हों, अपनी टोकरी की तली में रखें। दाने ऊपर डालें, फैलाने की ज़रूरत नहीं है, और ढक्कन बंद करें। (देखने के लिए ऊपर दी गई प्रक्रिया की तस्वीरें देखें।)",
"लगभग 7-8 मिनट एयर फ्राई करें, या जब तक दानों के फूटने की आवाज़ धीमी न पड़ जाए। लगभग 4-5 मिनट बाद फूटना शुरू हो जाना चाहिए। ध्यान रहे कि अलग-अलग मॉडल अलग रफ़्तार से काम करेंगे, इसलिए ढक्कन को बस इतना उठाकर कि अंदर झांक सकें, पॉपकॉर्न को ध्यान से देखें।",
"पॉपकॉर्न को एक बाउल में निकालें और चाहें तो मनचाही टॉपिंग डालें, या सादा ही खाएं।"],
["एल्युमीनियम फॉइल न भूलें। भले ही पंखे से वह खिसक या हिल सकती है, लेकिन यह कई दानों को फूटने का मौका मिलने से पहले आपकी टोकरी की तली के छोटे छेदों से गिरने से रोकेगी। पॉपकॉर्न बनाने के किसी भी तरीके की तरह, दानों के फूटना बंद करने पर कुछ बिना फूटे दाने बच जाएंगे, बस उन्हें फेंक दें। आपका पॉपकॉर्न ज़िप-टॉप बैग में कमरे के तापमान पर 3-4 दिन तक टिकेगा। बैग बंद करते समय जितनी हो सके उतनी हवा निकाल दें, ताकि आपका पॉपकॉर्न ताज़ा रहे।"],
[]),
(9809440,"एयर फ्रायर आड़ू [ओवन के निर्देशों के साथ]","मीठे, नरम, कैरामेल जैसे एयर फ्रायर आड़ू! आड़ू और क्रीम के लिए इन्हें नाइस क्रीम के साथ परोसें!","3 सर्विंग","1 सर्विंग",
["1 पाउंड ताज़े पके लेकिन सख्त आड़ू, लगभग 3 बड़े या 6 छोटे","वैकल्पिक मैरिनेड::2 बड़े चम्मच वीगन मक्खन, पिघला हुआ","वैकल्पिक मैरिनेड::2 बड़े चम्मच नारियल की शक्कर या ब्राउन शुगर","वैकल्पिक मैरिनेड::1 छोटा चम्मच दालचीनी","वैकल्पिक टॉपिंग::नाइस क्रीम","वैकल्पिक टॉपिंग::कटे हुए अखरोट या पीकन","वैकल्पिक टॉपिंग::ग्रेनोला या ओट्स, चाहें तो ग्लूटेन-मुक्त"],
["आड़ू को धोएं, काटें और गुठली निकाल दें। कटे हुए आड़ू एक छोटे मिक्सिंग बाउल में रखें और एक तरफ रख दें।",
"वैकल्पिक: एक और छोटे बाउल में मक्खन, शक्कर और दालचीनी मिलाएं। फिर मैरिनेड को कटे हुए आड़ू पर डालें और स्लाइस पर बराबर लगाने के लिए अच्छी तरह मिलाएं। (अगर आप अतिरिक्त वसा और चीनी से बच रहे हैं, तो आप इस मिश्रण के बिना भी आड़ू को सादा एयर फ्राई कर सकते हैं।)",
"कटे हुए आड़ू को अपनी फ्रायर की टोकरी में एक परत में सजाएं और 350°F/177°C पर 8-12 मिनट एयर फ्राई करें। वे तब तैयार होते हैं जब बहुत नरम हो जाएं और कांटा आड़ू के स्लाइस में आसानी से धंस जाए।",
"मनचाही टॉपिंग के साथ गरम परोसें या ऐसे ही खाएं।"],
["सबसे अच्छे स्वाद और कुदरती मिठास के लिए ताज़े पके हुए आड़ू इस्तेमाल करें। बड़े आड़ू को 6 स्लाइस में और छोटे आड़ू को 4 स्लाइस में काटें। आपके आड़ू कितने पके हैं, इससे पकने का समय तय होगा। ज़्यादा पके/नरम आड़ू कम पके/सख्त आड़ू से जल्दी पकेंगे। एयर फ्राई करते समय जो भी आड़ू के छिलके अलग हो जाएं, उन्हें हटा दें। नखरेबाज़ खाने वालों के लिए, आड़ू को काटने और एयर फ्राई करने से पहले छिलका उतार लें। पोषण संबंधी जानकारी में वैकल्पिक मैरिनेड शामिल है। इसमें मेवे और/या वनीला आइसक्रीम जैसी वैकल्पिक टॉपिंग शामिल नहीं हैं। मैरिनेड छोड़कर आड़ू को सादा पकाने से यह मिठाई वसा-मुक्त हो जाएगी और कैलोरी घटकर प्रति सर्विंग 64 कैलोरी रह जाएंगी।"],
[]),
]
P(3,R)
